1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.util.AddressNormalizer;
13	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
14	
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Locale;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
26	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
27	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
32	     * last names, as required by the API's read-only {@code displayName} field.
33	     *
34	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
35	     * applied only where referenced via {@code qualifiedByName}.
36	     */
37	    @Named("formatDisplayName")
38	    default String formatDisplayName(Owner owner) {
39	        if (owner == null) {
40	            return null;
41	        }
42	        return owner.getLastName() + ", " + owner.getFirstName();
43	    }
44	
45	    /**
46	     * Formats an owner's initials as the upper-cased first letters of the first and last
47	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
48	     * API's read-only {@code initials} field.
49	     *
50	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
51	     * applied only where referenced via {@code qualifiedByName}.
52	     */
53	    @Named("formatInitials")
54	    default String formatInitials(Owner owner) {
55	        if (owner == null) {
56	            return null;
57	        }
58	        return initial(owner.getFirstName()) + initial(owner.getLastName());
59	    }
60	
61	    /**
62	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
63	     * {@code customerCode} is the owner's customer code and {@code YY} is the last two
64	     * digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}), as required
65	     * by the API's read-only {@code membershipNumber} field. Returns {@code null} when
66	     * either the customer code or registration date is absent.
67	     *
68	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
69	     * applied only where referenced via {@code qualifiedByName}.
70	     */
71	    @Named("formatMembershipNumber")
72	    default String formatMembershipNumber(Owner owner) {
73	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
74	            return null;
75	        }
76	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
77	    }
78	
79	    private static String initial(String name) {
80	        if (name == null || name.isEmpty()) {
81	            return "";
82	        }
83	        return Character.toUpperCase(name.charAt(0)) + ".";
84	    }
85	
86	    Owner toOwner(OwnerDto ownerDto);
87	
88	    @Mapping(target = "id", ignore = true)
89	    @Mapping(target = "pets", ignore = true)
90	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
91	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
92	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
93	    Owner toOwner(OwnerFieldsDto ownerDto);
94	
95	    /**
96	     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
97	     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
98	     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
99	     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
100	     * {@code '12 MAIN STREET'}.
101	     *
102	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
103	     * only where referenced via {@code qualifiedByName}.
104	     */
105	    @Named("normalizeAddress")
106	    default String normalizeAddress(String address) {
107	        return AddressNormalizer.normalize(address);
108	    }
109	
110	    /**
111	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
112	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
113	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
114	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
115	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
116	     *
117	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
118	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
119	     *
120	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
121	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
122	     */
123	    @Named("normalizeTelephone")
124	    default String normalizeTelephone(String telephone) {
125	        return TelephoneNormalizer.toE164(telephone);
126	    }
